INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2228639, 302565, 30861, '<td valign="top">You was robbed. Utterly robbed...</td>', 'You was robbed. Utterly robbed...', '2006-03-15 00:28:00.000000', NULL, 0),
